"""Regenerate the editable TikZ figure used by resume7PT26.tex."""

from math import comb, cos, exp, isclose, pi, sqrt
from pathlib import Path


def coordinates(function, lower, upper, count=161):
    return " ".join(
        f"({x:.7f},{function(x):.7f})"
        for x in (lower + (upper - lower) * j / (count - 1) for j in range(count))
    )


def make_figure():
    parts = [
        "% Generated by generate_binomial_figure.py; do not edit the coordinates.",
        r"\begin{tikzpicture}[font=\small]",
    ]
    for n, offset in ((2, 2.1), (8, 7.1), (32, 12.1)):
        width = 2 / sqrt(n)
        masses = [comb(n, k) / 2**n for k in range(n + 1)]
        points = [(2 * k - n) / sqrt(n) for k in range(n + 1)]
        assert isclose(sum(masses), 1, abs_tol=1e-14)
        assert isclose(sum(z * mass for z, mass in zip(points, masses)), 0, abs_tol=1e-14)
        assert isclose(sum(z * z * mass for z, mass in zip(points, masses)), 1, abs_tol=1e-14)
        parts += [
            rf"\node[ink] at ({offset},5.02) {{$n={n}$}};",
            rf"\begin{{scope}}[xshift={offset}cm,yshift=2.75cm,x=0.53cm,y=3.6cm]",
            r"\node[ink] at (0,0.53) {$P(Z_n=z)/\Delta z$};",
        ]
        for z, mass in zip(points, masses):
            if abs(z) <= 3 + 1e-12:
                height = mass / width
                parts.append(
                    rf"\filldraw[fill=accent!18,draw=accent,line width=0.35pt] "
                    rf"({z-width/2:.7f},0) rectangle ({z+width/2:.7f},{height:.7f});"
                )
        parts += [
            r"\draw[ink,dashed,line width=0.85pt] plot coordinates {"
            + coordinates(lambda z: exp(-z*z/2)/sqrt(2*pi), -3.4, 3.4)
            + "};",
            r"\draw[ink,->] (-3.5,0)--(3.65,0) node[right] {$z$};",
            r"\draw[ink,->] (-3.5,0)--(-3.5,0.46);",
            r"\draw[muted!50] (-3.5,0.4)--(-3.34,0.4);",
            r"\node[ink,left] at (-3.5,0.4) {$0.4$};",
            r"\foreach \tick in {-2,0,2}{\draw[ink] (\tick,0)--(\tick,-0.015) node[below] {$\tick$};}",
            r"\end{scope}",
            rf"\begin{{scope}}[xshift={offset}cm,yshift=0.25cm,x=0.46cm,y=1.4cm]",
            r"\node[ink] at (0,1.35) {$\varphi_{Z_n}(t)$};",
            r"\draw[muted!30,dotted] (-4.2,1)--(4.2,1);",
            r"\draw[accent,line width=1pt] plot coordinates {"
            + coordinates(lambda t: cos(t/sqrt(n))**n, -4, 4)
            + "};",
            r"\draw[ink,dashed,line width=0.85pt] plot coordinates {"
            + coordinates(lambda t: exp(-t*t/2), -4, 4)
            + "};",
            r"\draw[ink,->] (-4.2,0)--(4.45,0) node[right] {$t$};",
            r"\draw[ink,->] (-4.2,0)--(-4.2,1.12);",
            r"\node[ink,left] at (-4.2,1) {$1$};",
            r"\foreach \tick in {-4,0,4}{\draw[ink] (\tick,0)--(\tick,-0.04) node[below] {$\tick$};}",
            r"\end{scope}",
        ]
    parts.append(r"\end{tikzpicture}")
    output = Path(__file__).with_name("binomial-characteristic.tex")
    output.write_text("\n".join(parts) + "\n", encoding="utf-8")
    print(f"Generated {output.name}; probabilities and moments verified for n=2,8,32.")


if __name__ == "__main__":
    make_figure()
